using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Reflection;using System.Windows.Forms;using MP1SkinStudio;
class SelectorProbe
{
 static readonly BindingFlags flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static List<string> results=new List<string>();static List<string> timings=new List<string>();
 static T Field<T>(object f,string name){return (T)f.GetType().GetField(name,flags).GetValue(f);}static object Call(object f,string name,params object[] args){try{return f.GetType().GetMethod(name,flags).Invoke(f,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Check(bool ok,string msg){if(!ok)throw new Exception(msg);}static void Test(string name,Action a){a();results.Add("PASS "+name);Console.WriteLine(results.Last());Console.Out.Flush();}
 static StudioMenu Open(ChoiceBox choice){return (StudioMenu)Call(choice,"OpenChoicesForTest");}static void Choose(StudioMenu menu,int index){Call(menu,"ChooseForTest",index);Application.DoEvents();}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Run(args);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(string[] args)
 {
  string demo=args[0],root=args[1],output=args[2];Directory.CreateDirectory(output);string[] pages=new SkinProject(root).Pages();Check(pages.Length>400,"Expected installed DefaultWideHD fixture");
  var originalHashes=Directory.GetFiles(root,"*.xml",SearchOption.AllDirectories).ToDictionary(p=>p,p=>ProjectFile.Digest(File.ReadAllBytes(p)));var demoHashes=Directory.GetFiles(demo,"*",SearchOption.AllDirectories).ToDictionary(p=>p,p=>ProjectFile.Digest(File.ReadAllBytes(p)));
  Test("449-file selector builds and reopens with bounded layout work and one active check",()=>
  {using(var f=new Form()){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);var c=new ChoiceBox{Size=new Size(230,28)};f.Controls.Add(c);c.Items.AddRange(pages.Cast<object>());c.SelectedIndex=5;var menu=StudioMenus.For(c,Field<string>(c,"menuKey"));int layouts=0;menu.Layout+=(s,e)=>layouts++;f.Show();Application.DoEvents();for(int i=0;i<3;i++){layouts=0;var sw=Stopwatch.StartNew();var next=Open(c);sw.Stop();timings.Add("Open "+(i+1)+": "+sw.ElapsedMilliseconds+" ms; "+layouts+" layouts; "+next.Items.Count+" items");Check(Object.ReferenceEquals(menu,next)&&next.Items.Count==pages.Length&&layouts<20&&next.Items.Cast<ToolStripMenuItem>().Count(m=>m.Checked)==1,"Unbounded layout work or bad menu contents");Check(((ToolStripMenuItem)next.Items[5]).Checked,"Selected entry lost check");next.Close();}f.Close();}});
  Test("Large selector dispatches first middle and last choices exactly once",()=>
  {using(var f=new Form()){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);var c=new ChoiceBox{Size=new Size(230,28)};f.Controls.Add(c);c.Items.AddRange(pages.Cast<object>());c.SelectedIndex=5;int events=0;c.SelectedIndexChanged+=(s,e)=>events++;f.Show();foreach(int index in new[]{0,pages.Length/2,pages.Length-1}){var menu=Open(c);int before=events;Choose(menu,index);Check(c.SelectedIndex==index&&events==before+1&&!menu.Visible&&!menu.IsDisposed,"Selection callback lost or duplicated");}f.Close();}});
  Test("Escape cancels large choices without changing selection or dispatching callbacks",()=>
  {using(var f=new Form()){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);var c=new ChoiceBox{Size=new Size(230,28)};f.Controls.Add(c);c.Items.AddRange(pages.Cast<object>());c.SelectedIndex=7;int events=0;c.SelectedIndexChanged+=(s,e)=>events++;f.Show();var menu=Open(c);Call(menu,"EscapeForTest");Application.DoEvents();Check(c.SelectedIndex==7&&events==0&&!menu.Visible&&!menu.IsDisposed,"Escape altered selection");f.Close();Check(menu.IsDisposed,"Owner did not dispose menu");}});
  Test("Reused selector drops old callbacks and safely escapes ampersands",()=>
  {using(var f=new Form()){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);var c=new ChoiceBox{Size=new Size(230,28)};f.Controls.Add(c);c.Items.AddRange(pages.Cast<object>());f.Show();Open(c).Close();c.Items.Clear();c.Items.AddRange(new object[]{"A & B","Other"});c.SelectedIndex=1;var menu=Open(c);Check(menu.Items.Count==2&&menu.Items[0].Text=="A && B","Old items survived or mnemonic escaped incorrectly");Choose(menu,0);Check(c.SelectedIndex==0,"Replacement callback used stale index");}});
  Test("DefaultWideHD real form page choices load Home Video Settings and retain edits through save reopen export",()=>
  {using(var f=new StudioForm(demo)){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.LoadProject(root,"myHome.xml");f.Show();Application.DoEvents();var choice=Field<ChoiceBox>(f,"page");Check(choice.Items.Count==pages.Length,"Page selector omitted files");var p=Field<SkinProject>(f,"project");var editable=p.Controls.First(c=>c.Node.Child("posX")!=null&&!c.IsBound("posX"));string source=editable.Source.RelativePath;int value;Check(Int32.TryParse(editable.Get("posX"),out value),"Non-numeric position fixture");p.Edit(editable,new Dictionary<string,string>{{"posX",(value+1).ToString()}},"Selector acceptance move");Call(f,"RefreshProject",editable.Key);string xml=editable.Source.Text;
   foreach(string page in new[]{"myvideo.xml","settings.xml","myHome.xml"}){int index=choice.FindStringExact(page);Check(index>=0,"Missing real page "+page);var sw=Stopwatch.StartNew();Choose(Open(choice),index);sw.Stop();timings.Add("Page "+page+": "+sw.ElapsedMilliseconds+" ms including menu, load, refresh and paint");Check(p.Page.Equals(page,StringComparison.OrdinalIgnoreCase)&&p.Sources.Values.Single(s=>s.RelativePath==source).Text==xml&&p.Undo.Count==1,"Page switch lost edit/history");}
   string project=Path.Combine(output,"DefaultWideHD.mp1skinproj"),zip=Path.Combine(output,"DefaultWideHD.zip");Call(f,"SaveSession",project);var restored=ProjectFile.Load(project);Check(restored.Sources.Values.Single(s=>s.RelativePath==source).Text==xml,"Saved edit not restored");restored.Export(zip);Check(File.Exists(zip),"No export");restored.UndoChange();Check(!restored.Dirty,"Restored Undo failed");restored.RedoChange();Check(restored.Sources.Values.Single(s=>s.RelativePath==source).Text==xml,"Restored Redo failed");
   string clean=Path.Combine(output,"DefaultWideHD-Review.mp1skinproj");var cleanProject=new SkinProject(root);cleanProject.OpenPage("myHome.xml");ProjectFile.Save(cleanProject,clean);
  }});
  Test("Pending fields still block the production page-change method and restore the selector",()=>
  {using(var f=new StudioForm(demo)){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.LoadProject(root,"myHome.xml");f.Show();Application.DoEvents();var fields=Field<Dictionary<string,TextBox>>(f,"fields");string key=fields.Keys.First(k=>fields[k].Enabled);fields[key].Text=fields[key].Text+" draft";var p=Field<SkinProject>(f,"project");string sig=ProjectFile.ContentSignature(p),before=p.Page;var choice=Field<ChoiceBox>(f,"page");typeof(StudioForm).GetField("loading",flags).SetValue(f,true);choice.SelectedIndex=choice.FindStringExact("myvideo.xml");typeof(StudioForm).GetField("loading",flags).SetValue(f,false);bool rejected=false;try{Call(f,"OpenSelectedPage");}catch(InvalidOperationException){rejected=true;}Check(rejected&&p.Page==before&&choice.SelectedItem.ToString()==before&&ProjectFile.ContentSignature(p)==sig&&fields[key].Text.EndsWith(" draft"),"Page menu bypassed pending guard");}});
  Test("Existing menu integration survives bulk clearing and anchor rebuilds",()=>
  {using(var f=new StudioForm(demo)){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();int checks=0;Call(f,"RunMenuUiSmoke",new Action<bool,string>((ok,name)=>{Check(ok,name);checks++;}));Check(checks>=10,"Existing menu integration incomplete");timings.Add("Existing menu integration: "+checks+" assertions passed");}});
  Check(originalHashes.All(p=>ProjectFile.Digest(File.ReadAllBytes(p.Key))==p.Value),"Installed XML changed");Check(demoHashes.All(p=>ProjectFile.Digest(File.ReadAllBytes(p.Key))==p.Value),"Demo assets changed");results.Add(results.Count+" passed, 0 failed; "+originalHashes.Count+" installed XML and "+demoHashes.Count+" demo hashes unchanged. Synthetic form/menu events; no desktop input.");File.WriteAllLines(Path.Combine(output,"Results.txt"),results);File.WriteAllLines(Path.Combine(output,"Timings.txt"),timings);Console.WriteLine(results.Last());foreach(string line in timings)Console.WriteLine(line);
 }
}
